<template>
  <main class="min-h-screen space-y-5 bg-white p-6">
    <header class="flex flex-wrap items-center justify-between gap-3"><div><h1 class="text-2xl font-bold text-slate-900">Financements</h1><p class="mt-1 text-sm text-slate-500">Suivi des financements prévus, confirmés, reçus et annulés.</p></div><button class="rounded-lg bg-bleu-nuit px-4 py-2 text-sm font-semibold text-white hover:opacity-90" @click="openForm">Ajouter un financement</button></header>
    <p v-if="error" class="rounded-lg bg-red-50 p-3 text-sm text-red-700">{{ error }}</p>
    <div class="overflow-x-auto rounded-xl border border-slate-200"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="p-3">Référence</th><th class="p-3">Projet</th><th class="p-3">Bailleur</th><th class="p-3">Date</th><th class="p-3">Statut</th><th class="p-3 text-right">Montant</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id" class="border-t border-slate-100"><td class="p-3 font-medium">{{ item.reference }}</td><td class="p-3">{{ item.projet_nom || item.projet }}</td><td class="p-3">{{ item.bailleur_nom || '—' }}</td><td class="p-3">{{ item.date }}</td><td class="p-3">{{ statusLabel(item.statut) }}</td><td class="p-3 text-right">{{ money(item.montant) }} {{ item.devise || 'XOF' }}</td></tr><tr v-if="!loading && !rows.length"><td colspan="6" class="p-8 text-center text-slate-500">Aucun financement enregistré.</td></tr></tbody></table></div>
    <div class="flex items-center justify-between text-sm text-slate-500"><span>{{ total }} financement(s)</span><div class="flex gap-2"><button :disabled="!previous || loading" class="rounded border px-3 py-1 disabled:opacity-40" @click="load(previous)">Précédent</button><button :disabled="!next || loading" class="rounded border px-3 py-1 disabled:opacity-40" @click="load(next)">Suivant</button></div></div>
    <div v-if="formOpen" class="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4" @click.self="formOpen = false"><form class="max-h-[90vh] w-full max-w-lg space-y-4 overflow-y-auto rounded-xl bg-white p-6 shadow-xl" @submit.prevent="save"><div class="flex items-center justify-between"><h2 class="text-lg font-bold text-slate-900">Nouveau financement</h2><button type="button" class="text-xl text-slate-500" aria-label="Fermer" @click="formOpen = false">×</button></div><label class="block text-sm font-medium text-slate-700">Projet<select v-model="form.projet" required class="mt-1 w-full rounded-lg border border-slate-200 p-2"><option value="">Sélectionner un projet</option><option v-for="p in projects" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><label class="block text-sm font-medium text-slate-700">Budget associé<select v-model="form.budget" data-live-validation-ignore class="mt-1 w-full rounded-lg border border-slate-200 p-2"><option value="">Aucun budget</option><option v-for="b in budgets" :key="b.id" :value="b.id">{{ b.projet_nom }} — {{ money(b.montant) }} FCFA</option></select></label><label class="block text-sm font-medium text-slate-700">Type<select v-model="form.type" class="mt-1 w-full rounded-lg border border-slate-200 p-2"><option value="BAILLEUR">Bailleur</option><option value="PARTENAIRE">Partenaire</option><option value="FONDS_PROPRES">Fonds propres</option><option value="CAMPAGNE">Campagne</option><option value="AUTRE">Autre</option></select></label><label class="block text-sm font-medium text-slate-700">Bailleur<select v-model="form.bailleur" class="mt-1 w-full rounded-lg border border-slate-200 p-2"><option value="">Aucun bailleur</option><option v-for="b in bailleurs" :key="b.id" :value="b.id">{{ b.nom }}</option></select></label><label class="block text-sm font-medium text-slate-700">Montant<input v-model.number="form.montant" required type="number" min="0.01" step="0.01" class="mt-1 w-full rounded-lg border border-slate-200 p-2" /></label><div class="grid grid-cols-2 gap-3"><label class="block text-sm font-medium text-slate-700">Devise<input v-model.trim="form.devise" required maxlength="10" class="mt-1 w-full rounded-lg border border-slate-200 p-2" /></label><label class="block text-sm font-medium text-slate-700">Date<input v-model="form.date" required type="date" class="mt-1 w-full rounded-lg border border-slate-200 p-2" /></label></div><label class="block text-sm font-medium text-slate-700">Statut<select v-model="form.statut" class="mt-1 w-full rounded-lg border border-slate-200 p-2"><option value="PREVU">Prévu</option><option value="CONFIRME">Confirmé</option><option value="RECU">Reçu</option><option value="ANNULE">Annulé</option></select></label><label class="block text-sm font-medium text-slate-700">Observation<textarea v-model.trim="form.observation" rows="2" class="mt-1 w-full rounded-lg border border-slate-200 p-2" /></label><p v-if="formError" class="text-sm text-red-600">{{ formError }}</p><div class="flex justify-end gap-2"><button type="button" class="rounded-lg border px-4 py-2 text-sm" @click="formOpen = false">Annuler</button><button :disabled="saving" class="rounded-lg bg-bleu-nuit px-4 py-2 text-sm font-semibold text-white disabled:opacity-60">{{ saving ? 'Enregistrement…' : 'Enregistrer' }}</button></div></form></div>
  </main>
</template>

<script setup>
import { onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import api from '@/services/api.js'
import { financeService } from '@/modules/finance/services/financeService.js'
const route = useRoute()
const rows = ref([]), projects = ref([]), budgets = ref([]), bailleurs = ref([]), loading = ref(false), error = ref(''), next = ref(null), previous = ref(null), total = ref(0)
const formOpen = ref(false), saving = ref(false), formError = ref('')
const today = new Date().toISOString().slice(0, 10)
const form = reactive({ projet: '', budget: '', bailleur: '', type: 'BAILLEUR', montant: '', devise: 'XOF', date: today, statut: 'CONFIRME', observation: '' })
const money = (value) => Number(value || 0).toLocaleString('fr-FR')
const statusLabel = (status) => ({ PREVU: 'Prévu', CONFIRME: 'Confirmé', RECU: 'Reçu', ANNULE: 'Annulé' }[status] || status)
async function load(url) { loading.value = true; error.value = ''; try { const response = url ? await api.get(url) : await financeService.fetchFinancements(); const data = response.data; rows.value = Array.isArray(data) ? data : data.results || []; next.value = Array.isArray(data) ? null : data.next; previous.value = Array.isArray(data) ? null : data.previous; total.value = Array.isArray(data) ? rows.value.length : data.count || rows.value.length } catch { error.value = 'Impossible de charger les financements.' } finally { loading.value = false } }
function openForm() { form.projet = ''; form.budget = String(route.query.budget || ''); form.bailleur = ''; form.type = 'BAILLEUR'; form.montant = ''; form.devise = 'XOF'; form.date = today; form.statut = 'CONFIRME'; form.observation = ''; formError.value = ''; formOpen.value = true }
async function save() { saving.value = true; formError.value = ''; const payload = { ...form, projet: form.projet, budget: form.budget || null, bailleur: form.bailleur || null, montant: Number(form.montant) }; try { await financeService.createFinancement(payload); formOpen.value = false; await load() } catch (e) { formError.value = e?.response?.data?.detail || Object.values(e?.response?.data || {}).flat().join(' ') || 'Impossible de créer le financement.' } finally { saving.value = false } }
async function list(url) { const { data } = await api.get(url); return Array.isArray(data) ? data : data.results || [] }
onMounted(async () => { try { [projects.value, budgets.value, bailleurs.value] = await Promise.all([list('/api/projects/'), financeService.fetchBudgets().then(({ data }) => Array.isArray(data) ? data : data.results || []), financeService.fetchBailleurs().then(({ data }) => Array.isArray(data) ? data : data.results || [])]) } catch { /* form controls show available records when loaded */ } await load(); if (route.query.budget) { openForm(); form.projet = budgets.value.find((item) => String(item.id) === String(route.query.budget))?.projet || '' } })
</script>
